const mcqs = [];

function addQ(id, topic, testTag, difficulty, question, options, answerIndex, explanation) {
    mcqs.push({
        id: `bio_${id.toString().padStart(3, '0')}`,
        subjectId: "biology",
        topic: topic,
        testTag: testTag,
        difficulty: difficulty,
        isPastPaper: true,
        question: question,
        options: options.map(String),
        answer: answerIndex,
        explanation: explanation || `Standard entrance test Biology question for ${topic} (${testTag}).`
    });
}

